import{_ as t,o,c as a,a2 as d}from"./chunks/framework.CDh-ZJvO.js";const g=JSON.parse('{"title":"功能特性","description":"","frontmatter":{},"headers":[],"relativePath":"guide/features.md","filePath":"guide/features.md","lastUpdated":null}'),r={name:"guide/features.md"};function l(i,e,c,n,s,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="功能特性" tabindex="-1">功能特性 <a class="header-anchor" href="#功能特性" aria-label="Permalink to &quot;功能特性&quot;">​</a></h1><p>晓雪WEB打印控件围绕&quot;<strong>让浏览器打得出、打得准、可管理</strong>&quot;设计，下面按能力维度介绍其核心特性。</p><h2 id="系统托盘驻留" tabindex="-1">系统托盘驻留 <a class="header-anchor" href="#系统托盘驻留" aria-label="Permalink to &quot;系统托盘驻留&quot;">​</a></h2><ul><li>服务启动后<strong>无主界面</strong>，常驻系统<strong>托盘</strong>，以 SWT 原生托盘与中文菜单呈现；</li><li>托盘<strong>左键双击</strong>打开打印任务列表，<strong>右键</strong>可访问任务列表、授权许可、关于与退出；</li><li>支持<strong>开机自启</strong>（安装时可勾选），打印服务随系统启动自动就绪。</li></ul><h2 id="本机-websocket-通信" tabindex="-1">本机 WebSocket 通信 <a class="header-anchor" href="#本机-websocket-通信" aria-label="Permalink to &quot;本机 WebSocket 通信&quot;">​</a></h2><ul><li>服务仅监听回环地址 <code>ws://127.0.0.1:54321</code>，<strong>不对外开放网卡端口</strong>，降低被外部访问的风险；</li><li>连接管理完善：自动重连、可配置重连间隔与最大次数、连接超时兜底、断线自动清理挂起请求。</li></ul><h2 id="真实打印-doprint" tabindex="-1">真实打印（doPrint） <a class="header-anchor" href="#真实打印-doprint" aria-label="Permalink to &quot;真实打印（doPrint）&quot;">​</a></h2><ul><li>将 <strong>text 文本</strong>或 <strong>HTML 片段</strong>渲染为 PDF 后，经 <strong>Java Print Service</strong> 输出到指定打印机；</li><li>支持任意本机已安装打印机，不弹系统打印对话框（静默打印）；</li><li>返回 <code>taskId</code>，任务异步执行、完成后自动清理。</li></ul><h2 id="分页预览-dopreview" tabindex="-1">分页预览（doPreview） <a class="header-anchor" href="#分页预览-dopreview" aria-label="Permalink to &quot;分页预览（doPreview）&quot;">​</a></h2><ul><li>不打印、仅打开预览窗口，<strong>所见即所得</strong>；</li><li>预览窗口提供：<strong>打印、页面设置、打印机设置、导出 PDF、导出图片、缩放、翻页、拖动、关闭</strong>等完整工具栏；</li><li>支持标尺、多页预览；相同 printer / style / content 的重复预览会<strong>激活已有窗口</strong>。</li></ul><h2 id="打印样式精细控制" tabindex="-1">打印样式精细控制 <a class="header-anchor" href="#打印样式精细控制" aria-label="Permalink to &quot;打印样式精细控制&quot;">​</a></h2><p>通过 <code>style</code> 字段可精确控制版式：</p><table tabindex="0"><thead><tr><th>样式项</th><th>说明</th></tr></thead><tbody><tr><td><code>paper</code></td><td>纸张（如 A4，或打印机支持的任意纸张）</td></tr><tr><td><code>direction</code></td><td>方向：<code>horizontal</code>（横向）/ <code>vertical</code>（纵向）</td></tr><tr><td><code>margin</code></td><td>页边距（cm）：<code>{ top, right, bottom, left }</code></td></tr><tr><td><code>zoom</code></td><td>缩放比例</td></tr><tr><td><code>fontFamily</code> / <code>fontSize</code></td><td>字体与字号（宋体、微软雅黑、黑体、楷体、仿宋、Arial 等）</td></tr><tr><td><code>paperHeader</code> / <code>paperFooter</code></td><td>页眉 / 页脚</td></tr></tbody></table><h2 id="打印机与纸张动态获取" tabindex="-1">打印机与纸张动态获取 <a class="header-anchor" href="#打印机与纸张动态获取" aria-label="Permalink to &quot;打印机与纸张动态获取&quot;">​</a></h2><ul><li><code>getPrinters()</code> 获取本机打印机列表；</li><li><code>getPageSize(printerName)</code> 获取指定打印机支持的纸张类型；</li><li>页面可据此动态渲染下拉选项，提升打印体验。</li></ul><h2 id="打印任务管理" tabindex="-1">打印任务管理 <a class="header-anchor" href="#打印任务管理" aria-label="Permalink to &quot;打印任务管理&quot;">​</a></h2><ul><li><code>getTaskList()</code> 获取任务列表，<code>getTaskStatus(taskId)</code> 查询单个任务；</li><li><code>cancelTask(taskId)</code> 取消<strong>待打印 / 打印中</strong>任务；</li><li><code>clearTasks()</code> 清除<strong>已完成 / 失败</strong>任务；</li><li>任务状态变化时，服务端主动向已连接客户端广播 <code>task_list_update</code> 事件，页面可实时刷新。</li></ul><h3 id="任务状态" tabindex="-1">任务状态 <a class="header-anchor" href="#任务状态" aria-label="Permalink to &quot;任务状态&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>说明</th><th>是否可取消</th></tr></thead><tbody><tr><td><code>PENDING</code></td><td>待打印</td><td>是</td></tr><tr><td><code>PRINTING</code></td><td>打印中</td><td>是</td></tr><tr><td><code>COMPLETED</code></td><td>已完成</td><td>否</td></tr><tr><td><code>FAILED</code></td><td>失败（可通过 <code>errorMessage</code> 查看原因）</td><td>否</td></tr></tbody></table><h2 id="bartender-标签打印" tabindex="-1">BarTender 标签打印 <a class="header-anchor" href="#bartender-标签打印" aria-label="Permalink to &quot;BarTender 标签打印&quot;">​</a></h2><p>深度集成 BarTender（bartender-printer-sdk 2.1.1）：</p><ul><li><code>getBartenderInstance()</code> 获取 BarTender 实例与版本信息（<code>available</code> / <code>version</code> / <code>fullVersion</code>）；</li><li><code>getTemplateParams(.btw)</code> 读取模板字段参数及控件类型（<code>Barcode</code> / <code>Text</code> / <code>Picture</code> / <code>RichText</code> / <code>RFID</code> 等）；</li><li><code>getTemplateImage(.btw)</code> / <code>getTemplateImageWithParams(.btw, params)</code> 获取模板图像（base64），支持<strong>带参数预览</strong>；</li><li>打印时可直接以 <code>content.type: &#39;bartender&#39;</code> 调用本机 BarTender 渲染或打印模板，适合条码、标签、证卡等场景。</li></ul><h2 id="授权许可" tabindex="-1">授权许可 <a class="header-anchor" href="#授权许可" aria-label="Permalink to &quot;授权许可&quot;">​</a></h2><ul><li>内置<strong>机器码</strong>展示与<strong>授权码</strong>输入、取消授权、邮箱联系入口；</li><li>授权相关代码经过 <strong>ProGuard 混淆</strong>与公钥加固，提升逆向门槛；</li><li>版本号由构建统一注入，托盘菜单与关于窗体自动展示。</li></ul><h2 id="跨平台-可配置" tabindex="-1">跨平台（可配置） <a class="header-anchor" href="#跨平台-可配置" aria-label="Permalink to &quot;跨平台（可配置）&quot;">​</a></h2><ul><li>默认面向 <strong>Windows x86_64</strong> 构建；</li><li>通过替换 <code>pom.xml</code> 中的 SWT artifact，可适配 <strong>macOS aarch64</strong>（<code>org.eclipse.swt.cocoa.macosx.aarch64</code>）与 <strong>Linux x86_64</strong>（<code>org.eclipse.swt.gtk.linux.x86_64</code>）。</li></ul><blockquote><p>需要了解整体架构与打印链路，请看<a href="./architecture">技术架构</a>。</p></blockquote>',27)])])}const b=t(r,[["render",l]]);export{g as __pageData,b as default};
